parameters.jsCode:
const items = $input.all();

const rows = items
  .map(item => item.json)
  .filter(item => item.title && item.link)
  .sort((a, b) => {
    const dateA = new Date(a.pubDate || a.isoDate || 0).getTime();
    const dateB = new Date(b.pubDate || b.isoDate || 0).getTime();
    return dateB - dateA;
  })
  .slice(0, 20)
  .map((item, index) => {
    const rawText = item.contentSnippet || item.content || item.description || "";

    const cleanText = String(rawText)
      .replace(/<[^>]*>/g, " ")
      .replace(/\s+/g, " ")
      .trim()
      .slice(0, 600);

    return {
      rank: index + 1,
      title: String(item.title),
      source: String(item.creator || item.source || item.author || ""),
      published: String(item.pubDate || item.isoDate || ""),
      url: String(item.link),
      summary: cleanText
    };
  });

const researchText = rows
  .map(item => {
    return [
      `#${item.rank} ${item.title}`,
      `Source: ${item.source}`,
      `Published: ${item.published}`,
      `URL: ${item.url}`,
      `Summary: ${item.summary}`
    ].join("\n");
  })
  .join("\n\n---\n\n");

return [
  {
    json: {
      research: researchText,
      articles: rows,
      articleCount: rows.length
    }
  }
];
